#include <stdio.h>

int main(void) {
    for (int i = 0; i < 4; i++) {
        printf("%d ", i * i);
    }
    printf("\n");
    int tries = 0;
    do {
        tries++;
    } while (tries < 0);
    printf("tries: %d\n", tries);
    return 0;
}

